#!/usr/bin/env python3
"""Build validation/evidence manifest offline after tests. No network or acquisition."""
from pathlib import Path
import json,re,platform,sys
from bs4 import BeautifulSoup
import bs4,requests
import municipal_codes_cli as m
ROOT=Path(__file__).resolve().parent

def main():
 report={'schema_version':1,'prepared_on':'2026-10-15','source_type':'municipal_codes','scope':'bounded source validation; no full corpus or import','parser_version':m.VERSION,'parser_sha256':m.sha((ROOT/'municipal_codes_cli.py').read_bytes()),'whole_corpus_validated':False,'status':'bounded_parser_and_primary_inventory_validated_full_scope_pending','runtime':{'python':platform.python_version(),'requests':requests.__version__,'beautifulsoup4':bs4.__version__,'optional_node_requirement':'20+','playwright_acquisition_runtime':'syntax checked only; live acquisition performed via supported CUA/IAB'},'tests':{'command':'python -m unittest -v test_municipal_codes validate_retained validate_live_snapshots','count':24,'passed':True,'evidence':'evidence/tests.log','coverage':{'synthetic_regressions':16,'retained_real_source_checks':4,'current_live_snapshot_checks':4},'human_visual_comparison':'Berkeley representative source inspected through CUA accessibility state; other live source checks automate DOM/header/body comparison, no whole-corpus human review'},'jurisdictions':[],'limitations':['Current official city-to-publisher routing confirmed only for Berkeley; remaining city links require ordinary operator follow-up.','Municipal code primary tree is fully retained at one point; additional family tree/scope validation remains pending.','One representative chapter per city: 54 section cards total, plus two preserved editorial parent-note bodies; no full-text corpus collected.','No start/end revision and inventory closure, no full publication currency coherence claim.','Difficult real tables, appendices, maps and long/nested provisions beyond this chapter remain unqualified; rich semantic regressions are synthetic.','All example exports explicitly incomplete; unresolved nodes/family scope must be resolved before downstream use.'],'acquisition_notes':['Direct HTTP discovery returned 403 for all5; immutable responses retained.','Chrome CUA setup policy failed twice; isolated supported IAB succeeded without access-control/CAPTCHA bypass.','Early large outerHTML captures were truncated by bridge; corrected with 50000-character chunks and verified against browser UTF16 length/link counts.','Early challenge/shell/truncated snapshots retained as rejected evidence and excluded from manifests.','Historical cache index can describe bytes overwritten later; retained fixture SHA256 identifies actual tested bytes.']}
 log=(ROOT/'evidence/tests.log').read_text()
 if not re.search(r'Ran 24 tests',log) or not log.rstrip().endswith('OK'):raise RuntimeError('Tests are not all passing; report not written')
 for slug,(name,disc,base) in m.ROUTES.items():
  d=ROOT/'evidence'/slug;inv=m.read_json(d/'inventory.json');chapter=m.read_json(d/'live-chapter-receipt.json');parsed=m.read_json(d/'live-parsed.json');pubs=m.read_json(d/'publications-discovery.json');example=m.read_json(ROOT/'examples'/slug/'validation-report.json');official=m.read_json(d/'official.json')
  entry={'slug':slug,'jurisdiction':name,'discovery_url':disc,'publication_base':base,'route_validation':{'direct_http':'blocked_403','supported_browser':'live_chapter_and_contents_reached','official_link_status':'confirmed' if slug=='berkeley-ca' else ('legacy_city_link_retained_redirect_unconfirmed' if slug=='sonoma-ca' else 'unconfirmed_city_landing_403'),'official_evidence':str((d/'official.json').relative_to(ROOT))},'parser_validation':{'status':'pass_bounded_live_and_retained_replay','current_section_cards':chapter['section_cards'],'parent_bodies':chapter['parent_bodies'],'retained_sample_date':'2026-08-28','live_dom_sha256':chapter['sha256'],'raw_currency_text':chapter['raw_currency_text'],'source_version_coherence':'unresolved_full_publication'},'inventory_validation':{'status':'primary_code_full_dom_captured_and_link_count_reconciled','nodes':len(inv['nodes']),'pending_controls':inv['pending_controls'],'families_complete':False,'complete_scope_qualification':False,'raw_sha256':inv['source_raw_sha256'],'source_inventory_path':str((d/'inventory.json').relative_to(ROOT))},'discovered_publications':pubs,'whole_corpus_validation':{'status':'not_run','validated':False,'example_included_records':example['record_count'],'unresolved_dispositions':example['unresolved_dispositions'],'exceptions':example['exceptions']},'evidence':[],'next_steps':['Confirm official city publisher redirect chain as applicable.','Qualify/disposition every discovered family and freeze its independent complete source tree.','Acquire remaining substantive nodes only in separately authorized full-corpus run; preserve parent/editorial status evidence.','Review representative difficult real structures and close source revision/inventory checks.']}
  for p in sorted(d.rglob('*')):
   if p.is_file():entry['evidence'].append({'path':str(p.relative_to(ROOT)),'sha256':m.sha(p.read_bytes()),'bytes':p.stat().st_size})
  report['jurisdictions'].append(entry)
 report['artifact_hashes']={str(p.relative_to(ROOT)):m.sha(p.read_bytes()) for p in sorted(ROOT.rglob('*')) if p.is_file() and '__pycache__' not in p.parts and p.name not in ('VALIDATION-REPORT.json','SHA256SUMS')}
 m.write_json(ROOT/'VALIDATION-REPORT.json',report)
 sums={**report['artifact_hashes'],'VALIDATION-REPORT.json':m.sha((ROOT/'VALIDATION-REPORT.json').read_bytes())}
 (ROOT/'SHA256SUMS').write_text(''.join(h+'  '+p+'\n' for p,h in sorted(sums.items())),encoding='utf-8')
 print(json.dumps({'jurisdictions':5,'tests':24,'inventory_nodes':sum(x['inventory_validation']['nodes'] for x in report['jurisdictions']),'sample_sections':sum(x['parser_validation']['current_section_cards'] for x in report['jurisdictions']),'whole_corpus_validated':False},indent=2))
if __name__=='__main__':main()
